<script setup lang="ts">import{ref,computed,onMounted}from 'vue';import{useRoute,useRouter}from 'vue-router';import{lab,load}from '../stores/research';import{canEdit}from '../stores/auth';import{create}from '../api/runs';import{create as createJoint}from '../api/jointRuns';import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const route=useRoute(),router=useRouter(),survey=ref(Number(route.query.survey)||0),a=ref(0),b=ref(0),perms=ref(499),seed=ref(157),name=ref('浮标圆周复核 · '+new Date().toLocaleTimeString()),{error,busy,execute}=useTask();const jointSurvey=ref(0),jointPerms=ref(499),jointSeed=ref(157),jointName=ref('多浮标联合研究 · '+new Date().toLocaleTimeString()),picked=ref<number[]>([]);const pickedCount=computed(()=>picked.value.length);onMounted(()=>execute(async()=>{await load();survey.value=survey.value||lab.surveys[0]?.id||0;jointSurvey.value=survey.value;a.value=lab.moorings[0]?.id||0;b.value=lab.moorings[1]?.id||0}));function submit(){execute(async()=>{const r=await create({name:name.value,survey_id:survey.value,mooring_a_id:a.value,mooring_b_id:b.value,permutations:perms.value,seed:seed.value});router.push('/results?run='+r.id)})}function submitJoint(){execute(async()=>{const r=await createJoint({name:jointName.value,survey_id:jointSurvey.value,mooring_ids:[...picked.value],permutations:jointPerms.value,seed:jointSeed.value});router.push('/results?joint='+r.id)})}</script><template><PageHeading index="03" title="先约定比较，再交换标签。" text="同一调查期两座浮标做双组研究；三座及以上用联合研究：统一重分全部标签，逐步最大值校正，避免逐对挑最小p夸大差异。"/><ErrorNotice :message="error" @retry="execute(load)"/><div class="configure-grid"><form @submit.prevent="submit"><p class="eyebrow">双组研究 / TWO GROUPS</p><label>研究名称<input v-model="name" required minlength="3" maxlength="160" :disabled="!canEdit"></label><label>调查期<select aria-label="调查期" v-model="survey" :disabled="!canEdit"><option v-for="s in lab.surveys" :value="s.id">{{s.name}}</option></select></label><div class="paired-inputs"><label>A组浮标<select aria-label="A组浮标" v-model="a" :disabled="!canEdit"><option v-for="m in lab.moorings" :value="m.id">{{m.name}}</option></select></label><label>B组浮标<select aria-label="B组浮标" v-model="b" :disabled="!canEdit"><option v-for="m in lab.moorings" :value="m.id">{{m.name}}</option></select></label></div><div class="paired-inputs"><label>标签置换次数<input v-model.number="perms" type="number" min="99" max="999" step="100" :disabled="!canEdit"></label><label>随机seed<input v-model.number="seed" type="number" min="0" max="2147483647" :disabled="!canEdit"></label></div><button v-if="canEdit" class="primary" :disabled="busy||a===b">排队计算圆周研究 →</button><p v-else class="margin-note">当前角色只读，可阅读研究和获批导出。</p></form><aside class="method-margin"><p class="eyebrow">METHOD BEFORE RESULT</p><h2>一个角度，<br>两个分布问题。</h2><ol><li>用单位向量计算均值方向和合向量R；弱合向量不强给方向。</li><li>拟合von Mises集中度，仅描述一个单峰圆周分布；双峰可能被一阶均值遮住。</li><li>energy基于弦距离比较整体分布，可反映位置和集中度差异。</li><li>标签置换要求独立、可交换观测；真实连续浮标数据常有自相关，须另行处理。</li></ol><p>不同组不允许重复引用；每组2–250条，空组会形成明确失败任务。p值最小为1/(B+1)，不作显著性自动行动。</p></aside></div><div class="configure-grid joint-grid"><form @submit.prevent="submitJoint"><p class="eyebrow">多浮标联合研究 / JOINT STEP-DOWN</p><label>研究名称<input v-model="jointName" required minlength="3" maxlength="160" :disabled="!canEdit"></label><label>调查期<select aria-label="联合研究调查期" v-model="jointSurvey" :disabled="!canEdit"><option v-for="s in lab.surveys" :value="s.id">{{s.name}}</option></select></label><fieldset class="mooring-checks"><legend>参与浮标 · 已选{{pickedCount}}座（3–32座）</legend><label v-for="m in lab.moorings" :key="m.id"><input type="checkbox" :value="m.id" v-model="picked" :disabled="!canEdit"><span>{{m.code}} · {{m.name}}</span></label></fieldset><div class="paired-inputs"><label>统一重分次数<input v-model.number="jointPerms" type="number" min="99" max="999" step="100" :disabled="!canEdit"></label><label>随机seed<input v-model.number="jointSeed" type="number" min="0" max="2147483647" :disabled="!canEdit"></label></div><button v-if="canEdit" class="primary" :disabled="busy||pickedCount<3||pickedCount>32">排队计算联合研究 →</button><p v-else class="margin-note">当前角色只读，可阅读研究和获批导出。</p></form><aside class="method-margin"><p class="eyebrow">ONE SHUFFLE, ALL PAIRS</p><h2>一次重分，<br>全部浮标对共享。</h2><ol><li>每次重分全部采样标签并保留各组大小，所有浮标对共用同一次置换。</li><li>沿用弦距离V统计量，各对并列整批计算。</li><li>按观测统计量降序做逐步最大值校正；校正p沿秩次单调、不小于原始p。</li><li>峰值内存预估超过256MB的口径直接拒绝；32座×100条×999次约十余秒。</li></ol><p>每次各对统计量随研究保存，供复算；页面与获批CSV分列原始p与校正p。</p></aside></div></template>
